SELECT p.gender, p.anchor_year, p.anchor_year_group, d.drg_mortality, AVG(i.los) AS average_length_of_stay, COUNT(DISTINCT l.labevent_id) AS initial_lab_events, COUNT(DISTINCT CASE WHEN l.value IS NOT NULL AND l.value_uom IS NOT NULL THEN l.labevent_id END) AS non_missing_lab_events, COUNT(DISTINCT CASE WHEN l.value IS NULL OR l.value_uom IS NULL THEN l.labevent_id END) AS missing_lab_events, SUM(CASE WHEN l.value IS NOT NULL AND l.value_uom IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(COUNT(DISTINCT l.labevent_id), 0) AS fraction_of_non_missing_labs, SUM(CASE WHEN l.value IS NULL OR l.value_uom IS NULL THEN 1 ELSE 0 END) / NULLIF(COUNT(DISTINCT l.labevent_id), 0) AS fraction_of_missing_labs FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND p.anchor_year BETWEEN 74 AND 84 AND d.drg_code = 'G571' AND l.charttime BETWEEN i.intime AND i.intime + INTERVAL '72 hours' GROUP BY p.gender, p.anchor_year, p.anchor_year_group, d.drg_mortality ORDER BY p.gender, p.anchor_year, p.anchor_year_group, d.drg_mortality NULLS LAST;